const statusTone = (status: PermitStatus) => ["APPROVED", "ACTIVE", "CLOSED"].includes(status) ? "good" : ["REJECTED", "CANCELLED", "EXPIRED"].includes(status) ? "bad" : ["DRAFT", "SUPERSEDED"].includes(status) ? "neutral" : "warn";
const displayStatus = (status: PermitStatus) => status === "INDIVIDUAL_REVIEW" ? "Pending Individual Reviewer approval" : status === "MT_REVIEW" ? "Pending MT Group approval" : status === "PM_REVIEW" ? "Pending PM approval" : STATUS_LABELS[status];
