function PageHeader({ eyebrow, title, text, action }: { eyebrow?: string; title: string; text: string; action?: React.ReactNode }) {
  return <header className="page-header"><div>{eyebrow && <span className="eyebrow">{eyebrow}</span>}<h1>{title}</h1><p>{text}</p></div>{action}</header>;
}

function StatusPill({ status, approvalDetail = false }: { status: PermitStatus; approvalDetail?: boolean }) {
  const reviewer = status === "INDIVIDUAL_REVIEW" ? "Individual Reviewer" : status === "MT_REVIEW" ? "MT Group" : status === "PM_REVIEW" ? "PM" : undefined;
  if (approvalDetail && reviewer) return <span className={`status-pill ${statusTone(status)} approval-status`}><span className="status-copy"><strong>Pending</strong><small>{reviewer} approval</small></span></span>;
  return <span className={`status-pill ${statusTone(status)}`}><i />{displayStatus(status)}</span>;
}

type DashboardMetricTone = "info" | "pending" | "approved" | "active" | "draft" | "rejected";
type DashboardMetric = { key: string; label: string; hint: string; permits: Permit[]; tone: DashboardMetricTone };
type DashboardMetricGroup = { title: string; metrics: DashboardMetric[] };

function Dashboard() {
  const { user, refresh, tick } = useApp();
  const all = useMemo(() => repository.listPermits(), [tick]);
  const own = all.filter((permit) => permit.requestorId === user.id);
  const reviewStatuses: PermitStatus[] = ["INDIVIDUAL_REVIEW", "MT_REVIEW", "PM_REVIEW"];
  const withStatus = (permits: Permit[], statuses: PermitStatus[]) => permits.filter((permit) => statuses.includes(currentRevision(permit).status));
  const requiringApproval = all.filter((permit) => availableActions(permit, user, all).some(({ action, decision }) => action === "APPROVE" && decision.allowed));
  const availablePermits = user.role === "CONTRACTOR_REQUESTOR" ? own : user.role === "MICRON_STAFF" ? visibleForUser(all, user, false) : all;
  const requestorMetrics = (permits: Permit[]): DashboardMetric[] => [
    { key: "raised", label: "Raised", hint: "All permits you submitted", permits, tone: "info" },
    { key: "draft", label: "Drafted permits", hint: "Saved and not submitted", permits: withStatus(permits, ["DRAFT"]), tone: "draft" },
    { key: "pending", label: "Pending approval", hint: "Awaiting reviewer decisions", permits: withStatus(permits, reviewStatuses), tone: "pending" },
    { key: "approved", label: "Approved permits", hint: "Approved and ready to activate", permits: withStatus(permits, ["APPROVED"]), tone: "approved" },
    { key: "rejected", label: "Rejected permits", hint: "Rejected by a reviewer", permits: withStatus(permits, ["REJECTED"]), tone: "rejected" },
  ];

  let groups: DashboardMetricGroup[];
  if (user.role === "CONTRACTOR_REQUESTOR") {
    groups = [{ title: "Awaiting approval", metrics: requestorMetrics(own) }];
  } else if (user.role === "CONTRACTOR_PM") {
    groups = [{
      title: "Pending my approval", metrics: [
        { key: "my-pm-approval", label: "Pending approval", hint: "Assigned to you at the PM stage", permits: requiringApproval, tone: "pending" },
        { key: "approved", label: "Approved permits", hint: "Approved permits across your view", permits: withStatus(all, ["APPROVED"]), tone: "approved" },
      ]
    }];
  } else if (user.role === "MICRON_STAFF") {
    groups = [
      {
        title: "Pending my approval", metrics: [
          { key: "my-pending", label: "Pending approval", hint: "Assigned to you for approval", permits: requiringApproval, tone: "pending" },
          { key: "my-approved", label: "Approved permits", hint: "Approved permits across your view", permits: withStatus(availablePermits, ["APPROVED"]), tone: "approved" },
        ]
      },
      { title: "Awaiting approval", metrics: requestorMetrics(own) },
    ];
  } else if (["SUPER_ADMIN", "USER_ADMIN"].includes(user.role)) {
    groups = [{
      title: "Permit overview", metrics: [
        { key: "total-permits", label: "Total permits", hint: "Pending, approved and rejected permits", permits: withStatus(all, [...reviewStatuses, "APPROVED", "REJECTED"]), tone: "info" },
        { key: "all-pending", label: "All pending approval", hint: "Across every approval stage", permits: withStatus(all, reviewStatuses), tone: "pending" },
        { key: "all-approved", label: "All approved permits", hint: "Approved and ready to activate", permits: withStatus(all, ["APPROVED"]), tone: "approved" },
        { key: "all-rejected", label: "All rejected permits", hint: "Rejected by a reviewer", permits: withStatus(all, ["REJECTED"]), tone: "rejected" },
      ]
    }];
  } else {
    groups = [{
      title: "Permit overview", metrics: [
        { key: "parent-permits", label: "Parent permits", hint: "Parent permits available to view", permits: all.filter((permit) => permit.type === "GENERAL"), tone: "info" },
        { key: "child-permits", label: "Child permits", hint: "Child permits available to view", permits: all.filter((permit) => permit.type === "HOT_WORK"), tone: "info" },
      ]
    }];
  }

  const metrics = groups.flatMap((group) => group.metrics);
  const [selectedMetric, setSelectedMetric] = useState("");
  const activeMetric = metrics.find((metric) => metric.key === selectedMetric);
  const displayedPermits = activeMetric?.permits ?? availablePermits;
  const reset = () => { if (confirm("Reset every local change and restore the walkthrough data?")) { repository.resetDemoData(); refresh(); } };
  return <div className="page"><PageHeader eyebrow="Operational control" title={`Welcome, ${user.name.split(" ")[0]}`} text={`${ROLE_LABELS[user.role]} view · ${new Intl.DateTimeFormat("en-SG", { dateStyle: "full" }).format(new Date())}`} action={<button className="button ghost" onClick={reset}>Reset demo data</button>} />
    <div className="dashboard-metric-groups">{groups.map((group) => <section className="dashboard-metric-group" key={group.title}><h2>{group.title}</h2><div className="stats">{group.metrics.map((metric) => <button type="button" className={`dashboard-metric ${metric.tone} ${activeMetric?.key === metric.key ? "selected" : ""}`} aria-pressed={activeMetric?.key === metric.key} onClick={() => setSelectedMetric(metric.key)} key={metric.key}><span>{metric.label}</span><strong>{metric.permits.length}</strong><small>{metric.hint}</small></button>)}</div></section>)}</div>
    <section className="card dashboard-results"><div className="card-heading"><div><h2>{activeMetric?.label ?? "All available permits"}</h2><p>{activeMetric ? "Showing permits included in the selected count." : "Showing every permit available to your role."}</p></div><Link to="/permits" className="text-link">View all →</Link></div>{displayedPermits.length ? <PermitRows permits={displayedPermits} /> : <Empty title={activeMetric ? `No ${activeMetric.label.toLowerCase()}` : "No available permits"} text="There are no permits matching this status for the selected identity." />}</section>
  </div>;
}

function visibleForUser(permits: Permit[], user: User, queue: boolean) {
  let list = user.role === "CONTRACTOR_REQUESTOR" ? permits.filter((p) => p.requestorId === user.id) : permits;
  if (user.role === "MICRON_STAFF") list = permits.filter((permit) => { const data = currentRevision(permit).data; const reviewerIds = data.individualReviewerIds?.length ? data.individualReviewerIds : [data.individualReviewerId]; const groups = data.mtGroups?.length ? data.mtGroups : [data.mtGroup]; return permit.requestorId === user.id || reviewerIds.includes(user.id) || groups.some((group) => isGroupMember(user, group)); });
  if (queue) list = list.filter((p) => availableActions(p, user, permits).some((a) => ["APPROVE", "REQUEST_CHANGES", "REJECT", "CLOSE"].includes(a.action) && a.decision.allowed));
  return list;
}

const permitStatusPriority: Record<PermitStatus, number> = {
  DRAFT: 0,
  INDIVIDUAL_REVIEW: 1,
  MT_REVIEW: 1,
  PM_REVIEW: 1,
  ACTIVE: 2,
  REJECTED: 3,
  CHANGES_REQUESTED: 4,
  APPROVED: 5,
  SUSPENDED: 6,
  CLOSURE_REQUESTED: 7,
  CLOSED: 8,
  CANCELLED: 9,
  EXPIRED: 10,
  SUPERSEDED: 11,
};

function sortPermitsByStatus(permits: Permit[]) {
  return [...permits].sort((a, b) => {
    const aRevision = currentRevision(a), bRevision = currentRevision(b);
    const priorityDifference = permitStatusPriority[aRevision.status] - permitStatusPriority[bRevision.status];
    if (priorityDifference) return priorityDifference;
    const aDate = aRevision.submittedAt ?? aRevision.createdAt;
    const bDate = bRevision.submittedAt ?? bRevision.createdAt;
    return bDate.localeCompare(aDate) || a.permitNumber.localeCompare(b.permitNumber);
  });
}

function PermitRows({ permits }: { permits: Permit[] }) {
  const orderedPermits = sortPermitsByStatus(permits);
  return <div className="permit-display"><div className="permit-table-wrap"><table className="permit-table"><thead><tr><th>Permit number<small>Code</small></th><th>Permit type<small>Work description</small></th><th>Discipline</th><th>Host / System owner</th><th>Applier site</th><th>Date applied</th><th>Work period</th><th>Status</th><th><span className="sr-only">Actions</span></th></tr></thead><tbody>{orderedPermits.map((permit) => { const rev = currentRevision(permit); return <tr className={rev.status === "DRAFT" ? "draft-permit-row" : undefined} key={permit.id}><td><Link className="permit-number" to={`/permits/${permit.id}`}>{permit.permitNumber}</Link><small>Code: {permitCode(permit)} · Rev {rev.number}{rev.status === "DRAFT" && <span className="draft-row-label">Draft permit</span>}</small></td><td><strong>{permitTypeLabel(permit)}</strong><small>{rev.data.title}</small></td><td>{rev.data.discipline}</td><td className="owner-cell">{findUser(rev.data.hostId).email}</td><td>{rev.data.site}</td><td>{formatDay(rev.submittedAt ?? rev.createdAt)}</td><td>{formatDay(rev.data.startAt)}<small>to {formatDay(rev.data.endAt)}</small></td><td><StatusPill status={rev.status} approvalDetail /></td><td><PermitActionMenu permit={permit} /></td></tr>; })}</tbody></table></div><div className="permit-mobile-list">{orderedPermits.map((permit) => { const rev = currentRevision(permit); return <Link className={`permit-mobile-card ${rev.status === "DRAFT" ? "draft-permit-row" : ""}`} to={`/permits/${permit.id}`} key={permit.id}><div className="mobile-card-main"><small>Permit number · {permitCode(permit)}{rev.status === "DRAFT" && <span className="draft-row-label">Draft permit</span>}</small><strong>{permit.permitNumber}</strong><span>{permitTypeLabel(permit)} · {rev.data.title}</span></div><StatusPill status={rev.status} /><dl><div><dt>Discipline</dt><dd>{rev.data.discipline}</dd></div><div><dt>Applier site</dt><dd>{rev.data.site}</dd></div><div><dt>Host / System owner</dt><dd>{findUser(rev.data.hostId).email}</dd></div><div><dt>Work period</dt><dd>{formatDay(rev.data.startAt)} – {formatDay(rev.data.endAt)}</dd></div></dl></Link>; })}</div></div>;
}

function MenuIcon({ name }: { name: "view" | "pdf" | "review" | "duplicate" }) {
  if (name === "view") return <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2.5 12s3.5-6 9.5-6 9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6Z" /><circle cx="12" cy="12" r="2.7" /></svg>;
  if (name === "pdf") return <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 2.8h8l4 4V21H6Z" /><path d="M14 2.8V7h4M8.5 16.5v-5h1.7a1.5 1.5 0 0 1 0 3H8.5m4 2v-5h1.4c1.5 0 2.4.9 2.4 2.5s-.9 2.5-2.4 2.5Z" /></svg>;
  if (name === "review") return <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 3h14v18H5Z" /><path d="m8 9 1.5 1.5L12 8m-4 7h8m-4-5h4" /></svg>;
  return <svg viewBox="0 0 24 24" aria-hidden="true"><rect x="8" y="8" width="11" height="11" rx="1" /><path d="M16 8V5H5v11h3" /></svg>;
}

function printPermit(permit: Permit) {
  const revision = currentRevision(permit), popup = window.open("", "_blank", "width=900,height=720");
  if (!popup) return;
  popup.opener = null; popup.document.title = `${permit.permitNumber} — ePTW`;
  const style = popup.document.createElement("style"); style.textContent = "body{font:14px Arial,sans-serif;color:#17243b;padding:32px}h1{color:#132d5c;font-size:22px;margin-bottom:5px}.meta{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:24px}.meta div{border-bottom:1px solid #ddd;padding:8px 0}.meta b{display:block;font-size:11px;text-transform:uppercase;color:#68778e;margin-bottom:3px}@media print{body{padding:0}}"; popup.document.head.appendChild(style);
  const heading = popup.document.createElement("h1"); heading.textContent = permit.permitNumber; popup.document.body.appendChild(heading);
  const subtitle = popup.document.createElement("p"); subtitle.textContent = `${permitTypeLabel(permit)} · ${displayStatus(revision.status)}`; popup.document.body.appendChild(subtitle);
  const meta = popup.document.createElement("div"); meta.className = "meta";
  [["Work description", revision.data.title], ["Discipline", revision.data.discipline], ["Host / System owner", findUser(revision.data.hostId).email], ["Applier site", revision.data.site], ["Date applied", formatDay(revision.submittedAt ?? revision.createdAt)], ["Work period", `${formatDay(revision.data.startAt)} to ${formatDay(revision.data.endAt)}`], ["Company", revision.data.company], ["Location", revision.data.location]].forEach(([label, value]) => { const item = popup.document.createElement("div"), key = popup.document.createElement("b"), text = popup.document.createElement("span"); key.textContent = label; text.textContent = value; item.append(key, text); meta.appendChild(item); });
  popup.document.body.appendChild(meta); popup.document.close(); popup.focus(); window.setTimeout(() => popup.print(), 250);
}

function PermitActionMenu({ permit }: { permit: Permit }) {
  const { user, refresh } = useApp(); const navigate = useNavigate(); const canDuplicate = canCreatePermit(user); const revision = currentRevision(permit);
  const duplicate = () => { if (!canDuplicate) return; try { const copy = repository.createPermit({ ...structuredClone(revision.data), title: `Copy of ${revision.data.title}` }, user); refresh(); navigate(`/permits/${copy.id}/edit`); } catch { /* Policy denial is represented by the disabled state. */ } };
  return <details className="row-menu"><summary aria-label={`Actions for ${permit.permitNumber}`}>⋯</summary><div className="row-menu-panel"><Link to={`/permits/${permit.id}`}><MenuIcon name="view" /><span>View</span></Link>{user.role !== "ASSESSOR" && <><button onClick={(event) => { printPermit(permit); event.currentTarget.closest("details")?.removeAttribute("open"); }}><MenuIcon name="pdf" /><span>Export as PDF</span></button><Link to={`/permits/${permit.id}#actions`}><MenuIcon name="review" /><span>Review</span></Link><button disabled={!canDuplicate} title={canDuplicate ? "Create a new draft from this permit" : "Only Requestors can duplicate permits"} onClick={duplicate}><MenuIcon name="duplicate" /><span>Duplicate</span></button></>}</div></details>;
}

function PermitList({ permitType = "GENERAL" }: { permitType?: Permit["type"] }) {
  const { user, tick } = useApp(); const location = useLocation(); const queue = new URLSearchParams(location.search).has("queue"); const [query, setQuery] = useState(""); const [status, setStatus] = useState(""); const [discipline, setDiscipline] = useState("");
  const all = useMemo(() => repository.listPermits(), [tick]); const filtered = visibleForUser(all, user, queue).filter((p) => { const r = currentRevision(p), text = `${p.permitNumber} ${r.data.title} ${r.data.description} ${r.data.company} ${findUser(r.data.hostId).email}`.toLowerCase(); return p.type === permitType && (!query || text.includes(query.toLowerCase())) && (!status || r.status === status) && (!discipline || r.data.discipline === discipline); });
  return <div className="page"><PageHeader eyebrow={queue ? "Assigned review" : "Permit register"} title={queue ? "Approval queue" : permitType === "HOT_WORK" ? "Child permits" : "Parent permits"} text={queue ? "Only permits where this identity can make the current decision are shown." : permitType === "HOT_WORK" ? "Linked child permits, including drafts and approval status." : "Parent permits, including drafts and approval status."} action={permitType === "GENERAL" && canCreatePermit(user) && <Link className="button primary" to="/permits/new">＋ Create permit</Link>} />
    <section className="card"><div className="filters"><label className="search"><span>⌕</span><input aria-label="Search permits" placeholder="Search permit number, owner or description" value={query} onChange={(e) => setQuery(e.target.value)} /></label><select aria-label="Filter by status" value={status} onChange={(e) => setStatus(e.target.value)}><option value="">All statuses</option>{Object.entries(STATUS_LABELS).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select><select aria-label="Filter by discipline" value={discipline} onChange={(e) => setDiscipline(e.target.value)}><option value="">All disciplines</option>{DISCIPLINES.map((item) => <option key={item}>{item}</option>)}</select><span className="result-count" aria-live="polite">{filtered.length} permit{filtered.length === 1 ? "" : "s"}</span></div>{filtered.length ? <PermitRows permits={filtered} /> : <Empty title="No permits found" text="Try changing your search or filters." />}</section>
  </div>;
}

