function LssFasPage() {
  const [query, setQuery] = useState(""); const [site, setSite] = useState(""); const [status, setStatus] = useState(""); const [from, setFrom] = useState(""); const [to, setTo] = useState(""); const [showEmpty, setShowEmpty] = useState(false);
  const filtered = LSS_FAS_RECORDS.filter((item) => { const searchText = `${item.permitNumber} ${item.parentNumber} ${item.reason} ${item.requester} ${item.host} ${item.area}`.toLowerCase(); const day = item.startAt.slice(0, 10); return (!query || searchText.includes(query.toLowerCase())) && (!site || item.site === site) && (!status || item.status === status) && (!from || day >= from) && (!to || day <= to); });
  const grouped = Object.entries(filtered.reduce<Record<string, LssFasRecord[]>>((result, item) => { const day = item.startAt.slice(0, 10); (result[day] ??= []).push(item); return result; }, {})).sort(([a], [b]) => b.localeCompare(a));
  const clear = () => { setQuery(""); setSite(""); setStatus(""); setFrom(""); setTo(""); };
  return <div className="page lss-page"><PageHeader eyebrow="Life safety systems" title="LSS / FAS impairment requests" text="Monitor controlled life-safety and fire-alarm system impairments by work date and Operations / EHS status." />
    <section className="card lss-register"><div className="lss-filters"><label className="search"><span>⌕</span><input aria-label="Search LSS/FAS permits" placeholder="Find permit, requester, reason or area" value={query} onChange={(event) => setQuery(event.target.value)} /></label><select aria-label="Filter LSS/FAS by site" value={site} onChange={(event) => setSite(event.target.value)}><option value="">All sites</option>{SITES.map((item) => <option key={item}>{item}</option>)}</select><select aria-label="Filter LSS/FAS by status" value={status} onChange={(event) => setStatus(event.target.value)}><option value="">All statuses</option>{Object.entries(LSS_STATUS_LABELS).map(([key, label]) => <option value={key} key={key}>{label}</option>)}</select><label className="date-filter"><span>From</span><input aria-label="LSS/FAS start date" type="date" value={from} onChange={(event) => setFrom(event.target.value)} /></label><label className="date-filter"><span>To</span><input aria-label="LSS/FAS end date" type="date" value={to} onChange={(event) => setTo(event.target.value)} /></label><button className="button ghost small" type="button" onClick={clear}>Clear</button></div>
      <div className="lss-result-bar"><div><strong>{filtered.length} request{filtered.length === 1 ? "" : "s"}</strong><span>Grouped by impairment start date</span></div><label className="show-empty-toggle"><input type="checkbox" checked={showEmpty} onChange={(event) => setShowEmpty(event.target.checked)} /> Show empty statuses</label></div>
      <div className="lss-groups">{grouped.length ? grouped.map(([day, records], groupIndex) => <details className="lss-date-group" key={day} open={groupIndex === 0}><summary><span>Impairment start date</span><strong>{formatDay(day)}</strong><div className="date-status-counts" aria-label={`Status counts for ${formatDay(day)}`}>{LSS_STATUS_ORDER.flatMap((statusKey) => { const count = records.filter((record) => record.status === statusKey).length; return count ? [<span className={`lss-status ${statusKey.toLowerCase()}`} key={statusKey}>{LSS_STATUS_LABELS[statusKey]}<span className="status-count-number">{count}</span></span>] : []; })}</div><b className="date-total-count" aria-label={`${records.length} total requests`}>{records.length}</b></summary><div className="lss-status-groups">{LSS_STATUS_ORDER.map((statusKey, statusIndex) => { const statusRecords = records.filter((record) => record.status === statusKey); if (!showEmpty && !statusRecords.length) return null; return <details className="lss-status-group" key={statusKey} open={groupIndex === 0 && (statusRecords.length > 0 || statusIndex === 0)}><summary><span>Operations / EHS status</span><strong className={`lss-status ${statusKey.toLowerCase()}`}>{LSS_STATUS_LABELS[statusKey]}</strong><b className={`section-status-count ${statusKey.toLowerCase()}`} aria-label={`${statusRecords.length} ${LSS_STATUS_LABELS[statusKey].toLowerCase()} requests`}>{statusRecords.length}</b></summary><LssFasTable records={statusRecords} /></details>; })}</div></details>) : <Empty title="No impairment requests found" text="Try changing the search, site, status, or date filters." compact />}</div>
    </section>
  </div>;
}

