function SippReportPage() {
  const years = [...new Set(SIPP_RECORDS.map((record) => record.startAt.slice(0, 4)))].sort().reverse();
  const [year, setYear] = useState(years[0] ?? String(new Date().getFullYear()));
  const [month, setMonth] = useState("02");
  const filtered = SIPP_RECORDS.filter((record) => record.startAt.startsWith(`${year}-${month}`));
  const grouped = Object.entries(filtered.reduce<Record<string, SippRecord[]>>((groups, record) => { const day = record.startAt.slice(0, 10); return { ...groups, [day]: [...(groups[day] ?? []), record] }; }, {})).sort(([left], [right]) => right.localeCompare(left));
  return <div className="page"><PageHeader eyebrow="SIPP reporting" title="SIPP daily reports" text="Review daily SIPP submissions by work date and approval status." /><section className="card lss-register sipp-register"><div className="sipp-filters"><Field label="Year"><select aria-label="Filter SIPP reports by year" value={year} onChange={(event) => setYear(event.target.value)}>{years.map((item) => <option key={item}>{item}</option>)}</select></Field><Field label="Month"><select aria-label="Filter SIPP reports by month" value={month} onChange={(event) => setMonth(event.target.value)}>{Array.from({ length: 12 }, (_, index) => { const value = String(index + 1).padStart(2, "0"); const label = new Intl.DateTimeFormat("en", { month: "long" }).format(new Date(2026, index, 1)); return <option value={value} key={value}>{label}</option>; })}</select></Field></div><div className="lss-result-bar"><div><strong>{filtered.length} report{filtered.length === 1 ? "" : "s"}</strong><span>Grouped by start date</span></div></div><div className="lss-groups">{grouped.length ? grouped.map(([day, records], groupIndex) => <details className="lss-date-group" key={day} open={groupIndex === 0}><summary><span>Start date / time</span><strong>{sippDay(day)}</strong><div className="date-status-counts" aria-label={`Status counts for ${sippDay(day)}`}>{SIPP_STATUS_ORDER.flatMap((statusKey) => { const count = records.filter((record) => record.status === statusKey).length; return count ? [<span className={`lss-status ${statusKey.toLowerCase()}`} key={statusKey}>{SIPP_STATUS_LABELS[statusKey]}<span className="status-count-number">{count}</span></span>] : []; })}</div><b className="date-total-count">{records.length}</b></summary><div className="lss-status-groups">{SIPP_STATUS_ORDER.map((statusKey) => { const statusRecords = records.filter((record) => record.status === statusKey); return <details className="lss-status-group" key={statusKey} open={groupIndex === 0 && statusRecords.length > 0}><summary><span>Status</span><strong className={`lss-status ${statusKey.toLowerCase()}`}>{SIPP_STATUS_LABELS[statusKey]}</strong><b className={`section-status-count ${statusKey.toLowerCase()}`}>{statusRecords.length}</b></summary><SippTable records={statusRecords} /></details>; })}</div></details>) : <Empty title="No SIPP reports found" text="There are no reports for the selected year and month." compact />}</div></section></div>;
}

const permitSchema = z.object({ title: z.string().min(3, "Enter a clear work title."), description: z.string().min(15, "Describe the work and controls."), site: z.string().min(1), discipline: z.string().min(1, "Select a discipline."), location: z.string().min(2, "Enter the exact work location."), company: z.string().min(2, "Enter the company."), startAt: z.string().min(1), endAt: z.string().min(1), hostId: z.string().min(1), individualReviewerId: z.string().min(1), mtGroup: z.string().min(1), hazards: z.array(z.string()), safetyDeclarations: z.array(z.string()), attachments: z.array(z.any()), hotWork: z.object({ fireWatchName: z.string(), fireWatchMobile: z.string(), gasTestingRequired: z.boolean(), combustibleMaterialsRemoved: z.boolean(), extinguishersAvailable: z.boolean() }).optional() }).superRefine((value, ctx) => { if (new Date(value.startAt) >= new Date(value.endAt)) ctx.addIssue({ code: "custom", message: "End time must be later than start time.", path: ["endAt"] }); });

function PermitFormPage() {
  const { id } = useParams(); const existing = id ? repository.getPermit(id) : undefined; const { user, refresh } = useApp(); const navigate = useNavigate(); const [step, setStep] = useState(1); const [error, setError] = useState(""); const initial = existing ? currentRevision(existing).data : blankPermitData();
  const parentTemplates = readTemplates().filter((template) => template.kind === "PARENT" && template.active);
  const [templateId, setTemplateId] = useState(existing ? initial.templateId ?? parentTemplates[0]?.id ?? "" : "");
  const [customFields, setCustomFields] = useState<Record<string, string | boolean>>(initial.customFields ?? {});
  const [safetyChecklistResponses, setSafetyChecklistResponses] = useState<SafetyChecklistResponses>(initial.safetyChecklistResponses ?? {});
  const [safetyTab, setSafetyTab] = useState<SafetyChecklistTabId>("health-safety");
  const [checklistErrors, setChecklistErrors] = useState<Record<string, string[]>>({});
  const [assessorId, setAssessorId] = useState(initial.assessorIds?.[0] ?? "");
  const [individualReviewerIds, setIndividualReviewerIds] = useState<string[]>(initial.individualReviewerIds?.length ? initial.individualReviewerIds : initial.individualReviewerId ? [initial.individualReviewerId] : []);
  const [mtGroups, setMtGroups] = useState<string[]>(initial.mtGroups?.length ? initial.mtGroups : initial.mtGroup ? [initial.mtGroup] : []);
  if (!canCreatePermit(user) || (existing && existing.requestorId !== user.id)) return <Navigate to="/permits" replace />;
  const toInput = (date: string) => new Date(date).toISOString().slice(0, 16); const defaults = { ...initial, startAt: toInput(initial.startAt), endAt: toInput(initial.endAt), hotWork: initial.hotWork ?? { fireWatchName: "", fireWatchMobile: "", gasTestingRequired: true, combustibleMaterialsRemoved: false, extinguishersAvailable: false } };
  const { register, handleSubmit, watch, setValue, getValues, formState: { errors } } = useForm<PermitFormData>({ resolver: zodResolver(permitSchema), defaultValues: defaults });
  const selectedTemplate = parentTemplates.find((template) => template.id === templateId);
  const reviewerOptions = USERS.filter((item) => item.role === "MICRON_STAFF").map((item) => ({ value: item.id, label: item.name, detail: item.email }));
  const mtGroupOptions = readGroups().map((group) => ({ value: group.name, label: group.name, detail: `${group.site} · ${group.memberIds?.length ?? 0} members` }));
  const changeReviewers = (values: string[]) => { setIndividualReviewerIds(values); setValue("individualReviewerId", values[0] ?? "", { shouldValidate: true }); };
  const changeMtGroups = (values: string[]) => { setMtGroups(values); setValue("mtGroup", values[0] ?? "", { shouldValidate: true }); };
  const selectTemplate = (nextId: string) => { setTemplateId(nextId); const template = parentTemplates.find((item) => item.id === nextId); if (template) { setValue("discipline", template.discipline); setValue("description", template.description); } };
  const validateSafetyChecklists = () => { const nextErrors = safetyChecklistErrors(safetyChecklistResponses); setChecklistErrors(nextErrors); if (Object.keys(nextErrors).length) { setStep(3); setError("Complete the required fields in each selected safety checklist."); return false; } return true; };
  const changeSafetyChecklists = (next: SafetyChecklistResponses) => { setSafetyChecklistResponses(next); if (Object.keys(checklistErrors).length) { const nextErrors = safetyChecklistErrors(next); setChecklistErrors(nextErrors); if (!Object.keys(nextErrors).length) setError(""); } };
  const continueStep = () => { if (step === 3 && !validateSafetyChecklists()) return; setStep((current) => current + 1); };
  const persistDraft = (values: PermitFormData) => { if (!existing && !selectedTemplate) { setError("Select a permit template before saving."); return; } const toStoredDate = (value: string) => value && !Number.isNaN(new Date(value).getTime()) ? new Date(value).toISOString() : value; const data = { ...values, individualReviewerId: individualReviewerIds[0] ?? "", individualReviewerIds, mtGroup: mtGroups[0] ?? "", mtGroups, templateId: selectedTemplate?.id ?? initial.templateId, templateName: selectedTemplate?.name ?? initial.templateName, customFields, safetyChecklistResponses, assessorIds: assessorId ? [assessorId] : [], startAt: toStoredDate(values.startAt), endAt: toStoredDate(values.endAt) }; const permit = existing ? repository.updateDraft(existing.id, data, user) : repository.createPermit(data, user); refresh(); navigate(`/permits/${permit.id}`); };
  const saveDraft = () => { if (!validateSafetyChecklists()) return; try { persistDraft(getValues()); } catch (e) { setError((e as Error).message); } };
  const save = handleSubmit((values) => { try { if (!validateSafetyChecklists()) return; const missingCustom = selectedTemplate?.sections?.flatMap((section) => section.fields).some((field) => field.required && (customFields[field.id] === undefined || customFields[field.id] === "" || customFields[field.id] === false)); if (missingCustom) { setStep(1); setError("Complete all required template fields before saving."); return; } persistDraft(values); } catch (e) { setError((e as Error).message); } }, () => { setStep(4); setError("Review the highlighted required fields before saving."); });
  const fieldError = (name: keyof typeof errors) => errors[name]?.message?.toString();
  return <div className="page form-page"><Link className="back-link" to={existing ? `/permits/${existing.id}` : "/permits"}>← Cancel and return</Link><PageHeader eyebrow={existing ? `Editing ${existing.permitNumber}` : "New controlled work"} title={existing ? "Edit permit revision" : "Create General Permit"} text="Complete each section. Safety requirements are checked again when you submit." />
    {!existing && <section className="card permit-setup"><div className="permit-setup-heading"><div><span>1</span><div><h2>Select permit setup</h2><p>Choose the template and approval route before completing the permit.</p></div></div>{selectedTemplate && <b>Template loaded</b>}</div><div className="permit-setup-grid"><Field label="Permit template type" error={!templateId && error ? "Select a permit template." : undefined}><select value={templateId} onChange={(event) => selectTemplate(event.target.value)}><option value="">Select permit template</option>{parentTemplates.map((template) => <option value={template.id} key={template.id}>{template.name}</option>)}</select></Field><Field label="Site"><select {...register("site")}>{SITES.map((site) => <option key={site}>{site}</option>)}</select></Field><Field label="Discipline"><select {...register("discipline")}>{DISCIPLINES.map((item) => <option key={item}>{item}</option>)}</select></Field><Field label="Host / System Owner"><select {...register("hostId")}><option value="">Select Host / System Owner</option>{USERS.filter((item) => item.role === "CONTRACTOR_PM").map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</select></Field><SearchMultiSelect label="Individual Reviewers" searchLabel="Search individual reviewers" placeholder="Select individual reviewers" options={reviewerOptions} values={individualReviewerIds} onChange={changeReviewers} /><SearchMultiSelect label="MT Groups" searchLabel="Search MT Groups" placeholder="Select MT Groups" options={mtGroupOptions} values={mtGroups} onChange={changeMtGroups} /></div>{selectedTemplate && <div className="selected-template"><span>{selectedTemplate.code}</span><div><strong>{selectedTemplate.name}</strong><p>{selectedTemplate.description}</p></div><small>{selectedTemplate.discipline}</small></div>}</section>}
    {(existing || selectedTemplate) && <><div className="template-form-label"><span>2</span><div><b>{selectedTemplate?.name ?? initial.templateName ?? "Permit details"}</b><small>Complete the selected template below.</small></div></div><div className="stepper">{["Work details", "Hazards", "Safety", "Review"].map((label, index) => <button type="button" className={step === index + 1 ? "current" : step > index + 1 ? "done" : ""} onClick={() => setStep(index + 1)} key={label}><b>{step > index + 1 ? "✓" : index + 1}</b><span>{label}</span></button>)}</div>
      <form className="card form-card" onSubmit={save}>
        {step === 1 && <FormSection title="Work scope and schedule" text="Use precise information so reviewers can assess the real work boundary."><div className="form-grid"><Field label="Work title" error={fieldError("title")} wide><input {...register("title")} /></Field><Field label="Company" error={fieldError("company")}><input {...register("company")} /></Field><Field label="Site"><select {...register("site")}>{SITES.map((s) => <option key={s}>{s}</option>)}</select></Field><Field label="Discipline" error={fieldError("discipline")}><select {...register("discipline")}>{DISCIPLINES.map((item) => <option key={item}>{item}</option>)}</select></Field><Field label="Exact work location" error={fieldError("location")}><input {...register("location")} /></Field><Field label="Preferred start"><input type="datetime-local" {...register("startAt")} /></Field><Field label="Preferred end" error={fieldError("endAt")}><input type="datetime-local" {...register("endAt")} /></Field><Field label="Work description and controls" error={fieldError("description")} wide><textarea rows={5} {...register("description")} /></Field></div></FormSection>}
        {step === 2 && <FormSection title="Hazard identification" text="Record general hazards. Accompanying EHS permits are selected in the Safety step."><div className="check-grid"><Check register={register("hazards")} value="ENERGY_ISOLATION" title="Energy isolation" text="Electrical, mechanical, pneumatic, or hydraulic energy" /><Check register={register("hazards")} value="WORK_AT_HEIGHT" title="Work at height" text="Work where a fall could cause injury" /></div></FormSection>}
        {step === 3 && <FormSection title="Safety confirmation" text="Select applicable checklist items and complete their required controls."><SafetyChecklistTabs activeTab={safetyTab} onTabChange={setSafetyTab} responses={safetyChecklistResponses} onChange={changeSafetyChecklists} /><SafetyChecklistResponseList activeTab={safetyTab} responses={safetyChecklistResponses} errors={checklistErrors} onChange={changeSafetyChecklists} /></FormSection>}
        {step === 4 && <FormSection title="Permit assignments and final review" text="Assignments grant permission only for this permit and current workflow stage."><div className="approval-route"><div><b>1</b><span>Individual review</span><small>{individualReviewerIds.map((id) => findUser(id).name).join(", ") || "Not assigned"}</small></div><i>→</i><div><b>2</b><span>MT Group review</span><small>{mtGroups.join(", ") || "Not assigned"}</small></div><i>→</i><div><b>3</b><span>Contractor PM review</span><small>{findUser(watch("hostId")).name}</small></div></div><div className="assessor-assignment"><Field label="Assigned Assessor" hint="Optional. Grants append-only readings access for assigned child permits."><select value={assessorId} onChange={(event) => setAssessorId(event.target.value)}><option value="">No assessor assigned</option>{USERS.filter((item) => item.role === "ASSESSOR").map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</select></Field></div><input type="hidden" {...register("hostId")} /><input type="hidden" {...register("individualReviewerId")} /><input type="hidden" {...register("mtGroup")} /><div className={`readiness ${isComplete({ ...watch(), individualReviewerIds, mtGroups, safetyChecklistResponses }, existing?.type ?? "GENERAL") ? "ready" : ""}`}><strong>{isComplete({ ...watch(), individualReviewerIds, mtGroups, safetyChecklistResponses }, existing?.type ?? "GENERAL") ? "Ready to save" : "Some required information is missing"}</strong><span>The permit will remain a draft until you explicitly submit it from the detail page.</span></div></FormSection>}
        {step === 1 && selectedTemplate?.sections?.map((section) => <FormSection key={section.id} title={section.title} text={section.description || "Complete the fields configured for this permit template."}><div className="form-grid dynamic-template-fields">{section.fields.map((field) => <DynamicTemplateField key={field.id} field={field} value={customFields[field.id]} onChange={(value) => setCustomFields({ ...customFields, [field.id]: value })} />)}</div></FormSection>)}
        {error && <div className="form-alert" role="alert">{error}</div>}<div className="form-actions"><div className="form-actions-left"><button type="button" className="button ghost" disabled={step === 1} onClick={() => setStep((s) => s - 1)}>Back</button><button type="button" className="button ghost" onClick={saveDraft}>Save as draft</button></div><span>Step {step} of 4</span>{step < 4 ? <button type="button" className="button primary" onClick={continueStep}>Continue</button> : <button className="button primary" type="submit">Save permit draft</button>}</div>
      </form></>}</div>;
}

function Field({ label, error, hint, wide, children }: { label: string; error?: string; hint?: string; wide?: boolean; children: React.ReactNode }) { return <label className={`field ${wide ? "wide" : ""}`}><span>{label}</span>{children}{hint && <small>{hint}</small>}{error && <small className="error">{error}</small>}</label>; }
function SearchMultiSelect({ label, searchLabel, placeholder, options, values, onChange }: { label: string; searchLabel: string; placeholder: string; options: { value: string; label: string; detail?: string }[]; values: string[]; onChange: (values: string[]) => void }) {
  const [query, setQuery] = useState(""); const visible = options.filter((option) => `${option.label} ${option.detail ?? ""}`.toLowerCase().includes(query.toLowerCase()));
  const toggle = (value: string) => onChange(values.includes(value) ? values.filter((item) => item !== value) : [...values, value]);
  return <div className="field multi-select-field"><span>{label}</span><details className="search-multi-select"><summary><span>{values.length ? `${values.length} selected` : placeholder}</span><i>⌄</i></summary><div className="multi-select-panel"><label className="search"><span>⌕</span><input aria-label={searchLabel} value={query} onChange={(event) => setQuery(event.target.value)} placeholder={searchLabel} /></label><div className="multi-select-actions"><small>{values.length} selected</small><button type="button" onClick={() => onChange([])}>Clear all</button></div><div className="multi-select-options">{visible.length ? visible.map((option) => <label key={option.value}><input type="checkbox" checked={values.includes(option.value)} onChange={() => toggle(option.value)} /><span><strong>{option.label}</strong>{option.detail && <small>{option.detail}</small>}</span></label>) : <p>No matching options.</p>}</div></div></details>{values.length > 0 && <div className="multi-select-chips">{values.map((value) => { const option = options.find((item) => item.value === value); return <button type="button" onClick={() => toggle(value)} aria-label={`Remove ${option?.label ?? value}`} key={value}>{option?.label ?? value}<span>×</span></button>; })}</div>}</div>;
}
function Check({ register, value, title, text }: { register: UseFormRegisterReturn; value: string; title: string; text: string }) { return <label className="hazard"><input type="checkbox" value={value} {...register} /><span><b>{title}</b><small>{text}</small></span></label>; }
const scrollToSafetyElement = (id: string) => document.getElementById(id)?.scrollIntoView({ behavior: "smooth", block: "start" });
function LocateIcon() { return <svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="5" /><path d="M12 2v3M12 19v3M2 12h3M19 12h3" /></svg>; }
function SafetyChecklistTabs({ activeTab, onTabChange, responses, onChange }: { activeTab: SafetyChecklistTabId; onTabChange: (tab: SafetyChecklistTabId) => void; responses: SafetyChecklistResponses; onChange: (responses: SafetyChecklistResponses) => void }) {
  const items = checklistItemsForTab(activeTab);
  const selectedItems = items.filter((item) => responses[item.id]);
  const toggle = (item: SafetyChecklistItem, selected: boolean) => { const next = { ...responses }; if (selected) next[item.id] = checklistResponse(item.kind); else delete next[item.id]; onChange(next); };
  const active = SAFETY_CHECKLIST_TABS.find((tab) => tab.id === activeTab)!;
  return <div className="safety-checklists" id="safety-checklist-top"><div className="safety-tab-list" role="tablist" aria-label="Safety checklist sections">{SAFETY_CHECKLIST_TABS.map((tab) => <button type="button" role="tab" id={`safety-tab-${tab.id}`} aria-selected={activeTab === tab.id} aria-controls={`safety-panel-${tab.id}`} className={activeTab === tab.id ? "active" : ""} onClick={() => onTabChange(tab.id)} key={tab.id}><b className="safety-tab-badge">{tab.badge}</b><span>{tab.shortLabel}</span></button>)}</div><div className="safety-tab-panel" role="tabpanel" id={`safety-panel-${activeTab}`} aria-labelledby={`safety-tab-${activeTab}`}><div className="safety-tab-intro"><div><h3 className="safety-panel-title"><b className="safety-tab-badge">{active.badge}</b>{active.label}</h3><p>{active.description}</p></div><span>{selectedItems.length} selected</span></div><div className="safety-checklist-items">{items.map((item) => <div className={`safety-checklist-item ${responses[item.id] ? "selected" : ""}`} key={item.id}><label><input type="checkbox" checked={Boolean(responses[item.id])} onChange={(event) => toggle(item, event.target.checked)} /><span>{item.reference && <b className="checklist-code">{item.reference}</b>}<strong>{item.label}</strong></span></label>{responses[item.id] && <button type="button" className="locate-form-button" aria-label={`Jump to ${item.label} form`} onClick={() => scrollToSafetyElement(`safety-form-${item.id}`)}><LocateIcon /></button>}</div>)}</div></div></div>;
}
function SafetyChecklistResponseList({ activeTab, responses, errors, onChange }: { activeTab: SafetyChecklistTabId; responses: SafetyChecklistResponses; errors: Record<string, string[]>; onChange: (responses: SafetyChecklistResponses) => void }) {
  const selected = Object.entries(responses).flatMap(([id, response]) => { const item = checklistItem(id); return item && item.tab === activeTab ? [[item, response] as const] : []; });
  const update = (itemId: string, field: string, value: string | boolean) => onChange({ ...responses, [itemId]: { ...responses[itemId], [field]: value } });
  if (!selected.length) return null;
  return <div className="safety-response-list" aria-label="Selected safety checklist details">{selected.map(([item, response]) => <SafetyChecklistResponseCard item={item} response={response} errors={errors[item.id] ?? []} onChange={(field, value) => update(item.id, field, value)} key={item.id} />)}<button type="button" className="safety-back-to-top" aria-label="Back to safety checklist" onClick={() => scrollToSafetyElement("safety-checklist-top")}>↑</button></div>;
}
function SafetyChecklistResponseCard({ item, response, errors, onChange }: { item: SafetyChecklistItem; response: Record<string, string | boolean>; errors: string[]; onChange: (field: string, value: string | boolean) => void }) {
  const input = (field: string) => String(response[field] ?? "");
  return <details id={`safety-form-${item.id}`} className={`safety-response-card ${errors.length ? "invalid" : ""}`} open><summary><span>{item.reference && <b className="checklist-code">{item.reference}</b>}<b>{item.label}</b></span><span className="safety-accordion-arrow" aria-label="Collapse checklist details" /></summary><div className="safety-response-content">
    {item.kind === "impact" && <div className="form-grid"><Field label="Work impact details *" wide><textarea required rows={3} value={input("impactDetails")} onChange={(event) => onChange("impactDetails", event.target.value)} /></Field><Field label="Controls and prerequisites *" wide><textarea required rows={3} value={input("controls")} onChange={(event) => onChange("controls", event.target.value)} /></Field><Field label="Reference or attachment notes" wide><input value={input("references")} onChange={(event) => onChange("references", event.target.value)} /></Field></div>}
    {item.kind === "permit" && <div className="form-grid"><Field label="Execution details *" wide><textarea required rows={3} value={input("executionDetails")} onChange={(event) => onChange("executionDetails", event.target.value)} /></Field><Field label="Micron permit / checklist reference" wide><input value={input("micronReference")} onChange={(event) => onChange("micronReference", event.target.value)} /></Field><label className="tick wide"><input type="checkbox" checked={response.hasExternalPermit === true} onChange={(event) => onChange("hasExternalPermit", event.target.checked)} /> A non-Micron sub-permit is required</label>{response.hasExternalPermit === true && <Field label="Non-Micron permit number *" wide><input required value={input("externalPermitNumber")} onChange={(event) => onChange("externalPermitNumber", event.target.value)} /></Field>}</div>}
    {(item.kind === "environmental" || item.kind === "environmental-other") && <div className="form-grid">{item.kind === "environmental-other" && <Field label="Environmental impact description *" wide><textarea required rows={3} value={input("impactDescription")} onChange={(event) => onChange("impactDescription", event.target.value)} /></Field>}<Field label="Assessment and control plan *" wide><textarea required rows={3} value={input("assessmentPlan")} onChange={(event) => onChange("assessmentPlan", event.target.value)} /></Field><Field label="EAI assessment reference *" wide><input required value={input("eaiReference")} onChange={(event) => onChange("eaiReference", event.target.value)} /></Field></div>}
    {errors.length > 0 && <p className="safety-response-error">Complete: {errors.join(", ")}.</p>}
  </div></details>;
}
function SafetyChecklistReview({ responses }: { responses: SafetyChecklistResponses | undefined }) {
  const entries = Object.entries(responses ?? {}).flatMap(([id, response]) => { const item = checklistItem(id); return item ? [[item, response] as const] : []; });
  if (!entries.length) return null;
  const labels: Record<string, string> = { impactDetails: "Work impact details", controls: "Controls and prerequisites", references: "Reference or attachment notes", executionDetails: "Execution details", micronReference: "Micron permit / checklist reference", externalPermitNumber: "Non-Micron permit number", impactDescription: "Environmental impact description", assessmentPlan: "Assessment and control plan", eaiReference: "EAI assessment reference", hasExternalPermit: "Non-Micron sub-permit required" };
  return <div className="safety-checklist-review"><h3>Selected safety checklists</h3>{entries.map(([item, response]) => <details key={item.id}><summary><span>{item.label}</span>{item.reference && <small>{item.reference}</small>}</summary><dl>{Object.entries(response).filter(([, value]) => value !== "" && value !== false).map(([key, value]) => <div key={key}><dt>{labels[key] ?? key}</dt><dd>{value === true ? "Yes" : String(value)}</dd></div>)}</dl></details>)}</div>;
}
function FormSection({ title, text, children }: { title: string; text: string; children: React.ReactNode }) { return <section className="form-section"><header><h2>{title}</h2><p>{text}</p></header>{children}</section>; }
function DynamicTemplateField({ field, value, onChange }: { field: TemplateField; value: string | boolean | undefined; onChange: (value: string | boolean) => void }) { if (field.type === "CHECKBOX") return <label className="hazard dynamic-check"><input type="checkbox" checked={value === true} onChange={(event) => onChange(event.target.checked)} required={field.required} /><span><b>{field.label}{field.required ? " *" : ""}</b><small>Select to confirm</small></span></label>; return <Field label={`${field.label}${field.required ? " *" : ""}`} wide={field.type === "TEXTAREA"}>{field.type === "TEXTAREA" ? <textarea rows={4} required={field.required} value={String(value ?? "")} onChange={(event) => onChange(event.target.value)} /> : field.type === "SELECT" ? <select required={field.required} value={String(value ?? "")} onChange={(event) => onChange(event.target.value)}><option value="">Select an option</option>{field.options?.map((option) => <option key={option}>{option}</option>)}</select> : <input type={field.type === "NUMBER" ? "number" : field.type === "DATE" ? "date" : "text"} required={field.required} value={String(value ?? "")} onChange={(event) => onChange(event.target.value)} />}</Field>; }

const actionLabels: Record<TransitionAction, string> = { SUBMIT: "Submit for review", APPROVE: "Approve stage", REQUEST_CHANGES: "Request changes", REJECT: "Reject permit", CANCEL: "Cancel permit", ACTIVATE: "Activate work", SUSPEND: "Suspend work", RESUME: "Resume work", REQUEST_CLOSURE: "Request closure", CLOSE: "Verify and close" };
const contextualActions = (status: PermitStatus): TransitionAction[] => status === "DRAFT" || status === "CHANGES_REQUESTED" ? ["SUBMIT", "CANCEL"] : ["INDIVIDUAL_REVIEW", "MT_REVIEW", "PM_REVIEW"].includes(status) ? ["APPROVE", "REQUEST_CHANGES", "REJECT"] : status === "APPROVED" ? ["ACTIVATE", "CANCEL"] : status === "ACTIVE" ? ["SUSPEND", "REQUEST_CLOSURE"] : status === "SUSPENDED" ? ["RESUME", "REQUEST_CLOSURE"] : status === "EXPIRED" ? ["REQUEST_CLOSURE"] : status === "CLOSURE_REQUESTED" ? ["CLOSE"] : [];
const needsComment = (a: TransitionAction) => ["REQUEST_CHANGES", "REJECT", "CANCEL", "SUSPEND", "RESUME", "REQUEST_CLOSURE", "CLOSE"].includes(a);

function PermitDetail() {
  const { id } = useParams(); const { user, refresh, tick } = useApp(); const navigate = useNavigate(); const [pending, setPending] = useState<TransitionAction>(); const [comment, setComment] = useState(""); const [message, setMessage] = useState("");
  const permit = useMemo(() => id ? repository.getPermit(id) : undefined, [id, tick]); const all = useMemo(() => repository.listPermits(), [tick]);
  if (!permit) return <Navigate to="/permits" replace />; const rev = currentRevision(permit), requestor = findUser(permit.requestorId), owner = user.id === permit.requestorId;
  const execute = (action: TransitionAction) => { try { repository.performTransition(permit.id, action, { comment }, user); setPending(undefined); setComment(""); setMessage(`${actionLabels[action]} completed.`); refresh(); } catch (e) { setMessage((e as Error).message); } };
  const makeRevision = () => { try { repository.createRevision(permit.id, user); refresh(); navigate(`/permits/${permit.id}/edit`); } catch (e) { setMessage((e as Error).message); } };
  const related = [...(permit.parentId ? all.filter((p) => p.id === permit.parentId) : []), ...all.filter((p) => permit.childIds.includes(p.id))];
  return <div className="page detail-page"><Link className="back-link" to="/permits">← Back to permits</Link><section className="permit-hero"><div className="hero-top"><div><span className="eyebrow">{permit.type === "HOT_WORK" ? "Hot Work child permit" : "General Permit"} · Revision {rev.number}</span><h1>{permit.permitNumber}</h1><p>{rev.data.title}</p></div><StatusPill status={rev.status} /></div><ApprovalProgress permit={permit} /></section>
    {message && <div className="notice" role="status">{message}<button aria-label="Dismiss" onClick={() => setMessage("")}>×</button></div>}
    <div className="detail-layout"><div className="detail-main"><section className="card summary-card"><div className="card-heading"><div><h2>Permit summary</h2><p>Current controlled revision</p></div>{owner && ["DRAFT", "CHANGES_REQUESTED"].includes(rev.status) && <Link className="button ghost small" to={`/permits/${permit.id}/edit`}>Edit draft</Link>}</div><dl className="summary-grid"><Info label="Requestor" value={requestor.name} /><Info label="Company" value={rev.data.company} /><Info label="Site" value={rev.data.site} /><Info label="Discipline" value={rev.data.discipline} /><Info label="Location" value={rev.data.location} /><Info label="Start" value={formatDate(rev.data.startAt)} /><Info label="End" value={formatDate(rev.data.endAt)} /><Info label="Host / owner" value={findUser(rev.data.hostId).name} /><Info label="Individual reviewers" value={(rev.data.individualReviewerIds?.length ? rev.data.individualReviewerIds : [rev.data.individualReviewerId]).map((id) => findUser(id).name).join(", ")} /><Info label="MT Groups" value={(rev.data.mtGroups?.length ? rev.data.mtGroups : [rev.data.mtGroup]).join(", ")} /><Info label="Work description" value={rev.data.description} wide /></dl></section>
      <section className="card section-card"><SectionTitle number="1" title="Hazards and safety controls" complete={isComplete(rev.data, permit.type)} /><div className="section-content"><div className="tag-list">{rev.data.hazards.length ? rev.data.hazards.map((h) => <span key={h}>{h.replaceAll("_", " ")}</span>) : <em>No hazards selected</em>}</div><div className="control-list">{SAFETY_DECLARATIONS.map((d) => <div key={d}><b>{rev.data.safetyDeclarations.includes(d) ? "✓" : "—"}</b><span>{d}</span></div>)}</div><SafetyChecklistReview responses={rev.data.safetyChecklistResponses} />{rev.data.hotWork && <div className="hot-summary"><h3>Legacy Hot Work controls</h3><Info label="Fire watch" value={`${rev.data.hotWork.fireWatchName} · ${rev.data.hotWork.fireWatchMobile}`} /><Info label="Gas testing" value={rev.data.hotWork.gasTestingRequired ? "Required" : "Not required"} /></div>}</div></section>
      <section className="card section-card"><SectionTitle number="2" title="Linked permits" complete={related.every((p) => ["APPROVED", "ACTIVE", "CLOSED"].includes(currentRevision(p).status))} /><div className="section-content">{related.length ? related.map((p) => <Link className="related-permit" to={`/permits/${p.id}`} key={p.id}><span>{p.type === "HOT_WORK" ? "HW" : "G"}</span><div><strong>{p.permitNumber}</strong><small>{currentRevision(p).data.title}</small></div><StatusPill status={currentRevision(p).status} /></Link>) : <Empty title="No linked permits" text="This work scope has no child permit dependencies." compact />}</div></section>
      <ActivityPanel permit={permit} />
      <section className="card section-card"><SectionTitle number="4" title="Revision history" complete /><div className="section-content revision-list">{[...permit.revisions].reverse().map((r) => <div key={r.id}><b>Revision {r.number}</b><StatusPill status={r.status} /><span>Created {formatDate(r.createdAt)} by {findUser(r.createdBy).name}</span></div>)}</div></section></div>
      <aside className="detail-side">{user.role !== "ASSESSOR" && <ActionPanel permit={permit} all={all} user={user} pending={pending} comment={comment} setPending={setPending} setComment={setComment} execute={execute} makeRevision={makeRevision} />}<AuditTimeline permit={permit} /></aside></div>
  </div>;
}

function ApprovalProgress({ permit }: { permit: Permit }) { const rev = currentRevision(permit); const current = rev.status; const steps = [{ label: "Submitted", done: !!rev.submittedAt, current: false }, ...rev.approvals.map((s) => ({ label: s.role === "INDIVIDUAL_REVIEWER" ? "Individual" : s.role === "MT_GROUP" ? "MT Group" : "Final PM", done: s.status === "APPROVED", current: (s.role === "INDIVIDUAL_REVIEWER" && current === "INDIVIDUAL_REVIEW") || (s.role === "MT_GROUP" && current === "MT_REVIEW") || (s.role === "PM" && current === "PM_REVIEW") }))]; return <div className="approval-progress">{steps.map((s, i) => <div className={`${s.done ? "done" : ""} ${s.current ? "current" : ""}`} key={s.label}><b>{s.done ? "✓" : i + 1}</b><span>{s.label}</span></div>)}</div>; }
function Info({ label, value, wide }: { label: string; value: string; wide?: boolean }) { return <div className={`info ${wide ? "wide" : ""}`}><dt>{label}</dt><dd>{value || "Not provided"}</dd></div>; }
function SectionTitle({ number, title, complete }: { number: string; title: string; complete: boolean }) { return <header className="section-title"><b>{number}</b><h2>{title}</h2><span>{complete ? "✓ Complete" : "Attention required"}</span></header>; }

function ActionPanel({ permit, all, user, pending, comment, setPending, setComment, execute, makeRevision }: { permit: Permit; all: Permit[]; user: User; pending?: TransitionAction; comment: string; setPending: (a?: TransitionAction) => void; setComment: (s: string) => void; execute: (a: TransitionAction) => void; makeRevision: () => void }) {
  const status = currentRevision(permit).status, actions = contextualActions(status); const canRevise = canCreatePermit(user) && user.id === permit.requestorId && ["APPROVED", "ACTIVE", "SUSPENDED", "EXPIRED"].includes(status);
  return <section className="card action-card" id="actions"><div className="card-heading"><div><h2>Available actions</h2><p>Checked against identity and stage.</p></div></div><div className="action-list">{actions.map((action) => { const decision = getActionDecision(permit, action, user, all, needsComment(action) ? "preview" : ""); return <div key={action}><button className={`button ${action === "APPROVE" || action === "ACTIVATE" || action === "CLOSE" || action === "SUBMIT" ? "primary" : "ghost"}`} disabled={!decision.allowed} title={decision.reason} onClick={() => needsComment(action) ? setPending(action) : execute(action)}>{actionLabels[action]}</button>{!decision.allowed && <small>{decision.reason}</small>}</div>; })}{canRevise && <button className="button ghost" onClick={makeRevision}>Create new revision</button>}{!actions.length && !canRevise && <p className="muted">No workflow action is available for this status.</p>}</div>{pending && <div className="decision-box"><label><span>Required reason / evidence</span><textarea autoFocus rows={4} value={comment} onChange={(e) => setComment(e.target.value)} /></label><div><button className="button ghost small" onClick={() => { setPending(undefined); setComment(""); }}>Cancel</button><button className="button primary small" disabled={!comment.trim()} onClick={() => execute(pending)}>Confirm</button></div></div>}</section>;
}

function ActivityPanel({ permit }: { permit: Permit }) { const { user, refresh } = useApp(); const [summary, setSummary] = useState(""); const [safe, setSafe] = useState(false); const [error, setError] = useState(""); const status = currentRevision(permit).status; const canAdd = ["ACTIVE", "SUSPENDED"].includes(status) && ((user.role === "REQUESTOR" && user.id === permit.requestorId) || user.role === "PM"); const add = () => { try { repository.addActivityLog(permit.id, { date: new Date().toISOString(), summary, safetyConfirmed: safe }, user); setSummary(""); setSafe(false); setError(""); refresh(); } catch (e) { setError((e as Error).message); } }; return <section className="card section-card"><SectionTitle number="3" title="Daily safety and activity log" complete={permit.activities.length > 0} /><div className="section-content">{canAdd && <div className="activity-form"><textarea placeholder="Record work progress, site conditions, and any controls checked…" value={summary} onChange={(e) => setSummary(e.target.value)} /><label className="tick"><input type="checkbox" checked={safe} onChange={(e) => setSafe(e.target.checked)} /> Required safety controls were checked</label><button className="button primary small" disabled={!summary.trim() || !safe} onClick={add}>Add dated log</button>{error && <p className="error">{error}</p>}</div>}<div className="activity-list">{permit.activities.map((a) => <article key={a.id}><b>✓</b><div><strong>{a.summary}</strong><span>{formatDate(a.createdAt)} · {findUser(a.actorId).name}</span></div></article>)}{!permit.activities.length && <Empty title="No activity recorded" text="Logs become available when work is active." compact />}</div></div></section>; }

function AuditTimeline({ permit }: { permit: Permit }) { return <section className="card audit-card"><div className="card-heading"><div><h2>Activity history</h2><p>Append-only workflow record</p></div></div><div className="timeline">{permit.audit.map((e) => <article key={e.id}><i /><div><strong>{e.action.replaceAll("_", " ").toLowerCase()}</strong><span>{findUser(e.actorId).name} · {ROLE_LABELS[e.actorRole]}</span>{e.fromStatus && e.toStatus && <small>{STATUS_LABELS[e.fromStatus]} → {STATUS_LABELS[e.toStatus]}</small>}{e.comment && <blockquote>{e.comment}</blockquote>}<time>{formatDate(e.at)}</time></div></article>)}</div></section>; }

function AuditPage() { const { user, tick } = useApp(); if (user.role !== "ADMIN") return <Navigate to="/dashboard" replace />; const events = repository.listPermits().flatMap((p) => p.audit.map((e) => ({ ...e, permitNumber: p.permitNumber }))).sort((a, b) => b.at.localeCompare(a.at)); return <div className="page"><PageHeader eyebrow="Read-only oversight" title="Audit register" text="All recorded lifecycle transitions across the local demonstration." /><section className="card audit-table"><div className="audit-row head"><span>Time</span><span>Permit</span><span>Actor</span><span>Action</span><span>Transition</span></div>{events.map((e) => <div className="audit-row" key={e.id}><span>{formatDate(e.at)}</span><span>{e.permitNumber}</span><span>{findUser(e.actorId).name}<small>{ROLE_LABELS[e.actorRole]}</small></span><span>{e.action.replaceAll("_", " ")}</span><span>{e.fromStatus ? `${STATUS_LABELS[e.fromStatus]} → ${e.toStatus ? STATUS_LABELS[e.toStatus] : ""}` : "—"}</span></div>)}</section></div>; }
function AccountSettings() { const { user, setUser } = useApp(); return <div className="page account-page"><PageHeader eyebrow="Personal settings" title="Account settings" text="Manage the signed-in prototype identity and role preview." /><div className="account-layout"><section className="card account-profile"><div className="account-avatar">{user.name.split(" ").map((part) => part[0]).slice(0, 2).join("")}</div><div><span>Current account</span><h2>{user.name}</h2><p>{user.email}</p><b>{ROLE_LABELS[user.role]}</b></div></section><section className="card account-controls"><div className="card-heading"><div><h2>Prototype role preview</h2><p>Switching identity changes navigation and workflow permissions.</p></div></div><div className="account-form"><label htmlFor="account-user">User and role</label><select id="account-user" value={user.id} onChange={(event) => setUser(findUser(event.target.value))}>{USERS.map((item) => <option key={item.id} value={item.id}>{item.name} · {ROLE_LABELS[item.role]}</option>)}</select><div className="role-summary"><span>Active role</span><strong>{ROLE_LABELS[user.role]}</strong><small>Permissions continue to be enforced by the centralized workflow policy.</small></div></div></section></div></div>; }
type TemplateKind = "PARENT" | "CHILD";
type TemplateFieldType = "TEXT" | "TEXTAREA" | "NUMBER" | "DATE" | "CHECKBOX" | "SELECT";
type TemplateField = { id: string; label: string; type: TemplateFieldType; required: boolean; options?: string[] };
type TemplateSection = { id: string; title: string; description: string; fields: TemplateField[] };
type PermitTemplate = { id: string; kind: TemplateKind; name: string; code: string; discipline: string; description: string; active: boolean; updatedAt: string; sections?: TemplateSection[] };
const standardSections = (): TemplateSection[] => [{ id: crypto.randomUUID(), title: "Additional work information", description: "Template-specific details required by the reviewer.", fields: [{ id: crypto.randomUUID(), label: "Equipment / system reference", type: "TEXT", required: true }] }];
const TEMPLATE_STORAGE = "eptw-templates:v1";
const templateSeeds: PermitTemplate[] = [
  { id: "tpl-parent-general", kind: "PARENT", name: "General Permit to Work", code: "G", discipline: "AMHS", description: "Standard parent permit for controlled maintenance and installation work.", active: true, updatedAt: "2026-09-08T08:00:00.000Z" },
  { id: "tpl-parent-facilities", kind: "PARENT", name: "Facilities Maintenance Permit", code: "FM", discipline: "Facilities", description: "Parent permit for building and utility maintenance activities.", active: true, updatedAt: "2026-09-08T08:00:00.000Z" },
  { id: "tpl-child-hotwork", kind: "CHILD", name: "Hot Work Permit", code: "HW", discipline: "Facilities", description: "Mandatory child permit for welding, cutting, grinding, and ignition sources.", active: true, updatedAt: "2026-09-08T08:00:00.000Z" },
  { id: "tpl-child-isolation", kind: "CHILD", name: "Equipment Isolation Checklist", code: "EI", discipline: "AMHS", description: "Child safety control for mechanical and electrical energy isolation.", active: true, updatedAt: "2026-09-08T08:00:00.000Z" },
];
const readTemplates = (): PermitTemplate[] => { try { const saved = localStorage.getItem(TEMPLATE_STORAGE); return saved ? JSON.parse(saved) as PermitTemplate[] : templateSeeds; } catch { return templateSeeds; } };

function LegacyTemplatePage() {
  const { user } = useApp(); const [kind, setKind] = useState<TemplateKind>("PARENT"); const [templates, setTemplates] = useState<PermitTemplate[]>(readTemplates); const [adding, setAdding] = useState(false); const [query, setQuery] = useState(""); const [stateFilter, setStateFilter] = useState(""); const [form, setForm] = useState({ name: "", code: "", discipline: DISCIPLINES[0], description: "" }); const [sections, setSections] = useState<TemplateSection[]>(standardSections);
  if (!canConfigure(user)) return <Navigate to="/dashboard" replace />;
  const visible = templates.filter((template) => template.kind === kind && (!query || `${template.name} ${template.code} ${template.description} ${template.discipline}`.toLowerCase().includes(query.toLowerCase())) && (!stateFilter || (stateFilter === "ACTIVE" ? template.active : !template.active))); const update = (next: PermitTemplate[]) => { setTemplates(next); localStorage.setItem(TEMPLATE_STORAGE, JSON.stringify(next)); };
  const submit = (event: React.FormEvent) => { event.preventDefault(); if (!form.name.trim() || !form.code.trim() || !form.description.trim() || sections.some((section) => !section.title.trim() || section.fields.some((field) => !field.label.trim()))) return; const template: PermitTemplate = { id: crypto.randomUUID(), kind, name: form.name.trim(), code: form.code.trim().toUpperCase(), discipline: form.discipline, description: form.description.trim(), sections, active: true, updatedAt: new Date().toISOString() }; update([template, ...templates]); setForm({ name: "", code: "", discipline: DISCIPLINES[0], description: "" }); setSections(standardSections()); setAdding(false); };
  const switchTab = (next: TemplateKind) => { setKind(next); setAdding(false); setSections(standardSections()); };
  const addSection = () => setSections([...sections, { id: crypto.randomUUID(), title: "", description: "", fields: [] }]);
  const updateSection = (sectionId: string, patch: Partial<TemplateSection>) => setSections(sections.map((section) => section.id === sectionId ? { ...section, ...patch } : section));
  const addField = (sectionId: string) => setSections(sections.map((section) => section.id === sectionId ? { ...section, fields: [...section.fields, { id: crypto.randomUUID(), label: "", type: "TEXT", required: false }] } : section));
  const updateField = (sectionId: string, fieldId: string, patch: Partial<TemplateField>) => setSections(sections.map((section) => section.id === sectionId ? { ...section, fields: section.fields.map((field) => field.id === fieldId ? { ...field, ...patch } : field) } : section));
  return <div className="page template-page"><PageHeader eyebrow="System management" title="Permit templates" text="Create and manage the controlled structures used for parent and child permits." action={<button className="button primary" onClick={() => setAdding(true)}>＋ Add {kind === "PARENT" ? "parent" : "child"} template</button>} />
    <section className="card template-workspace"><div className="template-tabs" role="tablist" aria-label="Template types"><button role="tab" aria-selected={kind === "PARENT"} className={kind === "PARENT" ? "active" : ""} onClick={() => switchTab("PARENT")}><span>Parent Template</span><b>{templates.filter((item) => item.kind === "PARENT").length}</b></button><button role="tab" aria-selected={kind === "CHILD"} className={kind === "CHILD" ? "active" : ""} onClick={() => switchTab("CHILD")}><span>Child Template</span><b>{templates.filter((item) => item.kind === "CHILD").length}</b></button></div>
      <div className="template-toolbar"><label className="search"><span>⌕</span><input aria-label="Search templates" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search template name, code or discipline" /></label><select aria-label="Filter templates by status" value={stateFilter} onChange={(event) => setStateFilter(event.target.value)}><option value="">All statuses</option><option value="ACTIVE">Active</option><option value="INACTIVE">Inactive</option></select><span className="result-count" aria-live="polite">{visible.length} template{visible.length === 1 ? "" : "s"}</span></div>
      {adding && <form className="template-form" onSubmit={submit}><div className="template-form-head"><div><h3>Add {kind === "PARENT" ? "Parent" : "Child"} Template</h3><p>This template will be stored separately under the selected template type.</p></div><button type="button" aria-label="Close form" onClick={() => setAdding(false)}>×</button></div><div className="template-form-grid"><Field label="Template name"><input required value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} placeholder={kind === "PARENT" ? "e.g. General Installation Permit" : "e.g. Hot Work Checklist"} /></Field><Field label="Template code"><input required maxLength={8} value={form.code} onChange={(event) => setForm({ ...form, code: event.target.value })} placeholder="e.g. G or HW" /></Field><Field label="Discipline"><select value={form.discipline} onChange={(event) => setForm({ ...form, discipline: event.target.value })}>{DISCIPLINES.map((item) => <option key={item}>{item}</option>)}</select></Field><Field label="Description" wide><textarea required rows={3} value={form.description} onChange={(event) => setForm({ ...form, description: event.target.value })} placeholder="Describe when this template should be used." /></Field></div><div className="template-form-actions"><button type="button" className="button ghost" onClick={() => setAdding(false)}>Cancel</button><button type="submit" className="button primary">Save {kind === "PARENT" ? "parent" : "child"} template</button></div></form>}
      <div className="template-table-wrap" role="tabpanel"><table className="template-table"><thead><tr><th>Template name<small>{kind === "PARENT" ? "Parent permit structure" : "Child permit / checklist"}</small></th><th>Description</th><th>Last updated</th><th>Status</th><th><span className="sr-only">Actions</span></th></tr></thead><tbody>{visible.map((template) => <tr key={template.id}><td><div className={`template-kind-icon ${template.kind.toLowerCase()}`}>{template.code}</div><strong>{template.name}</strong></td><td>{template.description}</td><td>{formatDay(template.updatedAt)}</td><td><span className={`template-status ${template.active ? "enabled" : ""}`}>{template.active ? "Active" : "Inactive"}</span></td><td><details className="row-menu"><summary aria-label={`Actions for ${template.name}`}>⋯</summary><div className="row-menu-panel"><button onClick={() => update(templates.map((item) => item.id === template.id ? { ...item, active: !item.active, updatedAt: new Date().toISOString() } : item))}><MenuIcon name="review" /><span>Set {template.active ? "inactive" : "active"}</span></button><button onClick={() => { const copy = { ...template, id: crypto.randomUUID(), name: `Copy of ${template.name}`, updatedAt: new Date().toISOString() }; update([copy, ...templates]); }}><MenuIcon name="duplicate" /><span>Duplicate</span></button></div></details></td></tr>)}</tbody></table>{!visible.length && <Empty title="No templates found" text="Try changing the search or status filter." compact />}</div><div className="template-mobile-list">{visible.map((template) => <article key={template.id}><div className={`template-kind-icon ${template.kind.toLowerCase()}`}>{template.code}</div><div><strong>{template.name}</strong><span>{template.kind === "PARENT" ? "Parent template" : "Child template"}</span><p>{template.description}</p></div><span className={`template-status ${template.active ? "enabled" : ""}`}>{template.active ? "Active" : "Inactive"}</span></article>)}</div>
    </section></div>;
}
