function DownloadSection({ title, description, resources }: { title: string; description: string; resources: DownloadResource[] }) {
  return <section className="card download-section"><div className="download-section-heading"><div><h2>{title}</h2><p>{description}</p></div><span>{resources.length} file{resources.length === 1 ? "" : "s"}</span></div>{resources.length ? <div className="download-list">{resources.map((resource) => <article className="download-row" key={resource.id}><span className="pdf-icon" aria-hidden="true">PDF</span><div className="download-file"><strong>{resource.title}</strong><small>{resource.fileName}</small></div><div className="download-updated"><span>Last updated</span><time>{resource.updated}</time></div><a className="download-action" href={`/downloads/${encodeURIComponent(resource.fileName)}`} download={resource.fileName} aria-label={`Download ${resource.title}`}><span aria-hidden="true">⇩</span> Download</a></article>)}</div> : <Empty title="No matching files" text="Try a different search term." compact />}</section>;
}

function UserGuideFeature({ resource }: { resource?: DownloadResource }) {
  if (!resource) return null;
  return <section className="card user-guide-feature"><div className="guide-illustration" aria-hidden="true"><span>?</span><i>ePTW</i></div><div className="guide-content"><span className="guide-eyebrow">Recommended starting point</span><h2>{resource.title}</h2><p>Use the latest guide for step-by-step instructions on creating, reviewing, approving, and closing permits.</p><div className="guide-meta"><span className="document-file-pill"><b>PDF</b>{resource.fileName}</span><span className="guide-updated"><small>Last updated</small>{resource.updated}</span></div></div><a className="button primary guide-download" href={`/downloads/${encodeURIComponent(resource.fileName)}`} download={resource.fileName} aria-label={`Download ${resource.title}`}><span aria-hidden="true">⇩</span> Download guide</a></section>;
}

function FormDownloadsPage() {
  const [query, setQuery] = useState("");
  const filtered = DOWNLOAD_RESOURCES.filter((resource) => `${resource.title} ${resource.fileName} ${resource.category}`.toLowerCase().includes(query.toLowerCase()));
  const forms = filtered.filter((resource) => resource.category === "Forms & checklists");
  const guides = filtered.filter((resource) => resource.category === "User guides");
  return <div className="page downloads-page"><PageHeader eyebrow="Help & resources" title="Form downloads" text="Download controlled checklists, signage, and guidance for permit activities." /><section className="card downloads-toolbar"><label className="search"><span>⌕</span><input aria-label="Search downloadable forms" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search forms, checklists, signage, or guides" /></label><div className="download-summary"><strong>{filtered.length}</strong><span>available files</span></div></section>{guides.length === 1 ? <UserGuideFeature resource={guides[0]} /> : <DownloadSection title="User guides" description="Reference material for using the ePTW system." resources={guides} />}<DownloadSection title="Forms & checklists" description="Controlled supporting documents for planning and executing work safely." resources={forms} /></div>;
}

type TutorialResource = { id: string; number: string; title: string; category: "Getting started" | "Permit types" | "Workflow"; updated: string };
const TUTORIAL_RESOURCES: TutorialResource[] = [
  { id: "intro", number: "01", title: "Introduction to ePTW", category: "Getting started", updated: "10 April 2026" },
  { id: "login", number: "02", title: "ePTW system login", category: "Getting started", updated: "10 April 2026" },
  { id: "user-guide", number: "03", title: "User guide", category: "Getting started", updated: "10 April 2026" },
  { id: "parent-child", number: "04", title: "Parent and child permits", category: "Workflow", updated: "10 April 2026" },
  { id: "hot-work", number: "05", title: "B1 Hot Work permit", category: "Permit types", updated: "10 April 2026" },
  { id: "confined-space", number: "06", title: "B2 Confined Space", category: "Permit types", updated: "10 April 2026" },
  { id: "lifting", number: "07", title: "B3 Lifting", category: "Permit types", updated: "10 April 2026" },
  { id: "work-height", number: "08", title: "B4 Work at Height", category: "Permit types", updated: "10 April 2026" },
  { id: "lss", number: "09", title: "B5 LSS", category: "Permit types", updated: "10 April 2026" },
  { id: "live-electrical", number: "10", title: "B6 Live Electrical", category: "Permit types", updated: "10 April 2026" },
  { id: "sipp", number: "11", title: "B7 SIPP", category: "Permit types", updated: "10 April 2026" },
  { id: "dirty-permit", number: "12", title: "B8 Dirty Permit", category: "Permit types", updated: "10 April 2026" },
  { id: "approval", number: "13", title: "Approval and rejection flow", category: "Workflow", updated: "10 April 2026" },
  { id: "closure", number: "14", title: "Requester initiates pending closure", category: "Workflow", updated: "10 April 2026" },
];

function TutorialLibraryPage() {
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState<"All" | TutorialResource["category"]>("All");
  const visible = TUTORIAL_RESOURCES.filter((tutorial) => (category === "All" || tutorial.category === category) && `${tutorial.number} ${tutorial.title} ${tutorial.category}`.toLowerCase().includes(query.toLowerCase()));
  return <div className="page tutorials-page"><PageHeader eyebrow="Help & resources" title="Tutorial videos" text="Learn the ePTW workflow through short, task-focused walkthroughs." /><section className="card tutorial-toolbar"><label className="search"><span>⌕</span><input aria-label="Search tutorial videos" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search tutorials or permit types" /></label><div className="tutorial-filters" role="group" aria-label="Filter tutorials by category">{(["All", "Getting started", "Permit types", "Workflow"] as const).map((item) => <button type="button" className={category === item ? "active" : ""} aria-pressed={category === item} onClick={() => setCategory(item)} key={item}>{item}</button>)}</div></section>{!query && category === "All" && <section className="tutorial-featured"><div className="tutorial-featured-visual"><span className="tutorial-play" aria-hidden="true">▶</span><small>01</small></div><div><span className="tutorial-eyebrow">Start here</span><h2>Introduction to ePTW</h2><p>Get familiar with the permit workspace, navigation, and the complete controlled-work lifecycle.</p><a href="/tutorial#intro">Watch introduction <span aria-hidden="true">→</span></a></div></section>}<div className="tutorial-results-heading"><div><h2>All tutorials</h2><p>Choose a topic to open its guided walkthrough.</p></div><span>{visible.length} video{visible.length === 1 ? "" : "s"}</span></div>{visible.length ? <section className="tutorial-grid">{visible.map((tutorial) => <article className="tutorial-card" key={tutorial.id}><div className="tutorial-thumbnail"><span aria-hidden="true">▶</span><b>{tutorial.number}</b></div><div className="tutorial-card-body"><span className="tutorial-category">{tutorial.category}</span><h3>{tutorial.title}</h3><p>Updated {tutorial.updated}</p><a href={`/tutorial#${tutorial.id}`} aria-label={`Watch ${tutorial.title}`}>Watch tutorial <span aria-hidden="true">→</span></a></div></article>)}</section> : <section className="card"><Empty title="No tutorials found" text="Try another search term or category." compact /></section>}</div>;
}
function ModulePage({ title, text }: { title: string; text: string }) { const location = useLocation(); if (title === "Analytics") return <AnalyticsPage />; if (title === "Child permits") return <PermitList permitType="HOT_WORK" />; if (title === "LSS / FAS permits") return <LssFasPage />; if (title === "SIPP Daily Report") return <SippReportPage />; if (title === "Drafts") return <Navigate to="/permits" replace />; const resource = new URLSearchParams(location.search).get("resource"); if (resource === "forms") return <FormDownloadsPage />; if (resource === "tutorials") return <TutorialLibraryPage />; const resourceContent = resource === "issue" ? { title: "Report issue", text: "Report a system problem or request support from the ePTW administration team." } : undefined; const pageTitle = resourceContent?.title ?? title; const pageText = resourceContent?.text ?? text; return <div className="page"><PageHeader eyebrow={resourceContent ? "Resources" : "ePTW workspace"} title={pageTitle} text={pageText} /><section className="card"><Empty title={`${pageTitle} module`} text="This navigation destination is reserved for the next functional draft increment." /></section></div>; }
function Empty({ title, text, compact }: { title: string; text: string; compact?: boolean }) { return <div className={`empty ${compact ? "compact" : ""}`}><b>◇</b><strong>{title}</strong><span>{text}</span></div>; }

function AuthenticatedRoutes() { const { user } = useApp(); return <Shell><Routes><Route path="/" element={<Navigate to="/dashboard" replace />} /><Route path="/dashboard" element={<Dashboard />} /><Route path="/permits" element={<PermitList />} /><Route path="/permits/new" element={<PermitFormPage />} /><Route path="/permits/:id/edit" element={<PermitFormPage />} /><Route path="/permits/:id" element={<PermitDetail />} /><Route path="/audit" element={<AuditPage />} /><Route path="/account" element={<AccountSettings />} /><Route path="/help" element={<ModulePage title="Help & resources" text="Guidance, permit procedures, and support contacts." />} /><Route path="/child-permits" element={<PermitList permitType="HOT_WORK" />} /><Route path="/drafts" element={<ModulePage title="Drafts" text="Incomplete permits owned by the current user." />} /><Route path="/lss-fas-permits" element={<ModulePage title="LSS / FAS permits" text="Life-safety and fire-alarm system permit register." />} /><Route path="/submitted-permits" element={<ModulePage title="Parent permits" text="Permits created by the current reviewer." />} /><Route path="/other-permits" element={<ModulePage title="Other permits" text="Permits visible outside the current user's submissions." />} /><Route path="/closure-cancellation" element={<ModulePage title="Closure & cancellation" text="Operational permits awaiting closure or cancellation action." />} /><Route path="/approval-history" element={<ModulePage title="Approval history" text="Completed decisions for the current reviewer." />} /><Route path="/child-approvals" element={<ModulePage title="Child permit approvals" text="Linked child permits requiring review." />} /><Route path="/analytics" element={canConfigure(user) ? <ModulePage title="Analytics" text="Review permit volumes, status trends, approval performance, and operational insights." /> : <Navigate to="/dashboard" replace />} /><Route path="/sipp-daily-report" element={canConfigure(user) ? <ModulePage title="SIPP Daily Report" text="Review daily SIPP activity and controlled-work reporting across sites." /> : <Navigate to="/dashboard" replace />} /><Route path="/settings/companies" element={<CompanyListPage user={user} />} /><Route path="/settings/sites" element={<SitesPage />} /><Route path="/settings/maps" element={<MapsPage user={user} />} /><Route path="/settings/users" element={<UsersPage user={user} />} /><Route path="/settings/templates" element={<TemplatePage />} /><Route path="/settings/disciplines" element={<DisciplinesPage user={user} />} /><Route path="/settings/mt-groups" element={<MtGroupsPage user={user} />} /><Route path="*" element={<Navigate to="/dashboard" replace />} /></Routes></Shell>; }

export default function App() {
  const storedId = localStorage.getItem("eptw-demo-user");
  const [user, setUserState] = useState<User | null>(() => storedId ? findUser(storedId) : null);
  const [tick, setTick] = useState(0);
  const loginDemo = (next: User) => { localStorage.setItem("eptw-demo-user", next.id); setUserState(next); };
  const registerTemporary = (next: User) => { localStorage.removeItem("eptw-demo-user"); setUserState(next); };
  const logout = () => { localStorage.removeItem("eptw-demo-user"); setUserState(null); };
  return <Routes>
    <Route path="/login" element={<LoginPage user={user} onDemoLogin={loginDemo} />} />
    <Route path="/register/micron" element={<MicronRegistrationPage user={user} onRegister={registerTemporary} />} />
    <Route path="/register/contractor" element={<ContractorRegistrationPage user={user} onRegister={registerTemporary} />} />
    <Route path="/tutorial" element={<TutorialPage user={user} />} />
    <Route path="*" element={user ? <AppContext.Provider value={{ user, setUser: loginDemo, logout, tick, refresh: () => setTick((n) => n + 1) }}><AuthenticatedRoutes /></AppContext.Provider> : <Navigate to="/login" replace />} />
  </Routes>;
}
